#!/usr/bin/env python3
"""Minimal VT screen emulator for observing walk's output."""
import re, sys

class Screen:
    def __init__(self, rows, cols):
        self.rows, self.cols = rows, cols
        self.clear()
        self.cx = self.cy = 0
        self.fg = self.bg = None
        self.attrs = set()

    def clear(self):
        self.grid = [[(' ', None, None, frozenset()) for _ in range(self.cols)] for _ in range(self.rows)]

    def put(self, ch, w=1):
        if 0 <= self.cy < self.rows and 0 <= self.cx < self.cols:
            self.grid[self.cy][self.cx] = (ch, self.fg, self.bg, frozenset(self.attrs))
            for i in range(1, w):
                if self.cx + i < self.cols:
                    self.grid[self.cy][self.cx+i] = ('', None, None, frozenset())
        self.cx += w

    def feed(self, data: bytes):
        s = data.decode('utf-8', errors='replace')
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '\x1b':
                if i+1 < n and s[i+1] == ']':
                    # OSC: consume to BEL or ST
                    j = data.find(b'\x07', i) if isinstance(data, str) else None
                    m = re.match(r'\x1b\].*?(?:\x07|\x1b\\)', s[i:], re.S)
                    i += m.end() if m else n - i
                    continue
                if i+1 < n and s[i+1] == '[':
                    m = re.match(r'\x1b\[([0-9;?]*)([A-Za-z@`~])', s[i:])
                    if not m:
                        i += 2
                        continue
                    params, final = m.group(1), m.group(2)
                    self.csi(params, final)
                    i += m.end()
                    continue
                i += 2
                continue
            if c == '\r':
                self.cx = 0; i += 1; continue
            if c == '\n':
                self.cy += 1; i += 1; continue
            if c == '\x07':
                i += 1; continue
            w = 2 if _wide(c) else 1
            self.put(c, w)
            i += 1

    def csi(self, params, final):
        p = params.lstrip('?')
        nums = [int(x) if x else 0 for x in p.split(';')] if p else [0]
        if final in 'Hf':
            self.cy = (nums[0] or 1) - 1 if len(nums) > 0 else 0
            self.cx = (nums[1] or 1) - 1 if len(nums) > 1 else 0
            self.cy = min(self.cy, self.rows-1); self.cx = min(self.cx, self.cols-1)
        elif final == 'J':
            if not nums or nums[0] in (0, 2, 3):
                self.clear()
        elif final == 'K':
            if 0 <= self.cy < self.rows:
                for x in range(self.cx, self.cols):
                    self.grid[self.cy][x] = (' ', None, None, frozenset())
        elif final == 'm':
            if not p:
                self.fg = self.bg = None; self.attrs = set(); return
            k = 0
            while k < len(nums):
                v = nums[k]
                if v == 0:
                    self.fg = self.bg = None; self.attrs = set()
                elif v in (1,2,3,4,5,7,9):
                    self.attrs.add(v)
                elif v == 38 and k+2 < len(nums) and nums[k+1] == 5:
                    self.fg = nums[k+2]; k += 2
                elif v == 48 and k+2 < len(nums) and nums[k+1] == 5:
                    self.bg = nums[k+2]; k += 2
                elif v == 39: self.fg = None
                elif v == 49: self.bg = None
                k += 1
        elif final == 'A': self.cy = max(0, self.cy - (nums[0] or 1))
        elif final == 'B': self.cy = min(self.rows-1, self.cy + (nums[0] or 1))
        elif final == 'C': self.cx = min(self.cols-1, self.cx + (nums[0] or 1))
        elif final == 'D': self.cx = max(0, self.cx - (nums[0] or 1))
        elif final == 'G': self.cx = min(self.cols-1, (nums[0] or 1)-1)
        elif final == 'd': self.cy = min(self.rows-1, (nums[0] or 1)-1)

    def render(self, with_attrs=True):
        out = []
        for row in self.grid:
            line = ''
            last = None
            for (ch, fg, bg, at) in row:
                key = (fg, bg, at)
                if with_attrs and key != last:
                    line += f'<{fmt(fg)},{fmt(bg)}{","+",".join(str(a) for a in sorted(at)) if at else ""}>'
                    last = key
                line += ch if ch else ''
            out.append(line.rstrip())
        return '\n'.join(out)

def fmt(v):
    return '.' if v is None else str(v)

def _wide(ch):
    import unicodedata
    return unicodedata.east_asian_width(ch) in 'WF'
